after.code:
function pageWindow(items, page, size) {
  if (!Number.isSafeInteger(size) || size <= 0) throw new RangeError('size must be a positive safe integer');
  if (!Number.isSafeInteger(page)) throw new RangeError('page must be a safe integer');
  const totalPages = Math.max(1, Math.ceil(items.length / size));
  page = Math.max(1, Math.min(page, totalPages));
  const start = (page - 1) * size;
  return { page, totalPages, items: items.slice(start, start + size) };
}

tests:
const input = Object.freeze([1, 2, 3, 4, 5]);
for (const [page, expected] of [[1, {page:1,totalPages:3,items:[1,2]}], [2, {page:2,totalPages:3,items:[3,4]}], [3, {page:3,totalPages:3,items:[5]}], [0, {page:1,totalPages:3,items:[1,2]}], [Number.MIN_SAFE_INTEGER, {page:1,totalPages:3,items:[1,2]}], [Number.MAX_SAFE_INTEGER, {page:3,totalPages:3,items:[5]}]]) {
  const result = pageWindow(input, page, 2);
  if (JSON.stringify(result) !== JSON.stringify(expected)) throw new Error('分页或夹取错误: ' + page);
  if (result.items === input) throw new Error('必须返回新数组');
}

for (const page of [Number.MIN_SAFE_INTEGER, 1, Number.MAX_SAFE_INTEGER]) {
  const result = pageWindow([], page, 2);
  if (JSON.stringify(result) !== JSON.stringify({page:1,totalPages:1,items:[]})) throw new Error('空数组处理错误');
}

for (const size of [1, 2, Number.MAX_SAFE_INTEGER]) {
  const result = pageWindow([1, 2], Number.MAX_SAFE_INTEGER, size);
  const expected = size === 1 ? {page:2,totalPages:2,items:[2]} : {page:1,totalPages:1,items:[1,2]};
  if (JSON.stringify(result) !== JSON.stringify(expected)) throw new Error('边界页大小处理错误');
}

const invalid = [1.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1, Number.MIN_SAFE_INTEGER - 1, '2', null, undefined, true, 2n];
for (const field of ['page', 'size']) {
  const values = field === 'size' ? invalid.concat([0, -0, -1]) : invalid;
  for (const value of values) {
    let caught;
    try { pageWindow([], field === 'page' ? value : 1, field === 'size' ? value : 2); } catch (error) { caught = error; }
    if (!(caught instanceof RangeError)) throw new Error(field + ' 应抛出 RangeError: ' + String(value));
  }
}
